const runs = $input.all().map(i => i.json || {});
const sent = runs.filter(r => r.email_sent === true || r._parse_error === null).length;
const skipped = runs.filter(r => !r.email).length;
const errors = runs.filter(r => r._parse_error).length;

return [{ json: {
  messenger_run_id: `messenger-${Date.now()}`,
  sent,
  skipped,
  errors,
  total: runs.length,
} }];

