const pinecone = $input.first().json || {};
const vectors = pinecone.vectors || {};
const campaignId = Object.keys(vectors)[0] || 'agentyx';
const vector = vectors[campaignId] || {};
const m = vector.metadata || {};

const fallbackMeta = {
  campaign_id: 'agentyx',
  product_name: 'Agentyx',
  product_desc: 'Plataforma de automatizacion inteligente con IA y agentes digitales para empresas LATAM',
  from_name: 'LEV Innovation',
  from_email: 'prospector@levinnovation.com',
  subject_template: '[COMPANY] + IA = 40% menos costos operativos',
  sales_email: 'fleon@levinnovation.com',
  leads_per_run: 25,
  fit_threshold: 75
};
const meta = Object.keys(m).length > 0 ? m : fallbackMeta;

const campaign = {
  id: meta.campaign_id || campaignId,
  campaign_id: meta.campaign_id || campaignId,
  product: {
    name: meta.product_name || 'Agentyx',
    description: meta.product_desc || ''
  },
  email: {
    from_name: meta.from_name || 'LEV Innovation',
    from_email: meta.from_email || 'prospector@levinnovation.com',
    subject_template: meta.subject_template || '[COMPANY] + IA'
  },
  sales_team: {
    notification_emails: [meta.sales_email || 'fleon@levinnovation.com'],
    interest_keywords: Array.isArray(meta.interest_keywords) ? meta.interest_keywords : ['interesado','demo']
  }
};

// Lead data viene del nodo Check Email Status
const leadData = $('Check Email Status').item.json || {};
return [{ json: { ...leadData, campaign } }];

